application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');

:root { --ink:#17212b; --muted:#71808c; --cream:#f7f5ef; --card:#fffefa; --line:#e4e7e3; --teal:#0c7c78; --coral:#ed725e; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; background:var(--cream); color:var(--ink); font-family:'DM Sans',sans-serif; }
body:before { content:''; position:fixed; width:380px; height:380px; border-radius:50%; background:#dcefeb; top:-170px; right:-120px; z-index:-1; }
.page-shell { width:min(940px, calc(100% - 32px)); margin:0 auto; padding:55px 0 28px; }
.quiz-card { background:var(--card); border:1px solid #e9e8df; border-radius:24px; box-shadow:0 18px 50px rgba(35,53,56,.08); overflow:hidden; }
.quiz-header { padding:42px 52px 30px; border-bottom:1px solid var(--line); }
.eyebrow { color:var(--coral); font-size:11px; letter-spacing:2px; font-weight:700; margin-bottom:13px; }
h1 { font-family:'Space Grotesk',sans-serif; font-size:clamp(31px,5vw,48px); line-height:1.05; margin:0 0 12px; letter-spacing:-1.5px; }
.quiz-header p { color:var(--muted); margin:0; font-size:16px; }
.questions { padding:10px 52px 8px; }
.question { border:0; border-bottom:1px solid var(--line); padding:28px 0 30px; margin:0; min-width:0; }
.question:last-child { border-bottom:0; }
legend { display:flex; align-items:flex-start; gap:16px; width:100%; font-family:'Space Grotesk',sans-serif; font-weight:600; font-size:18px; line-height:1.35; padding:0; }
.question-number { flex:none; color:var(--teal); font-size:12px; letter-spacing:1px; padding-top:4px; }
.options { display:grid; grid-template-columns:repeat(3,1fr); gap:11px; margin:20px 0 0 38px; }
.option { border:1px solid var(--line); border-radius:10px; padding:13px 14px; cursor:pointer; color:#4d5a62; font-size:14px; display:flex; align-items:center; gap:10px; transition:.18s ease; }
.option:hover { border-color:#9ccbc5; background:#f4fbfa; }
.option input { position:absolute; opacity:0; pointer-events:none; }
.custom-radio { width:16px; height:16px; border:1.5px solid #b6c0c0; border-radius:50%; position:relative; flex:none; }
.option:has(input:checked) { color:var(--teal); border-color:var(--teal); background:#edf8f6; font-weight:600; }
.option:has(input:checked) .custom-radio { border-color:var(--teal); }
.option:has(input:checked) .custom-radio:after { content:''; width:8px; height:8px; border-radius:50%; background:var(--teal); position:absolute; inset:3px; }
.action-row { display:flex; align-items:center; justify-content:flex-end; gap:20px; padding:25px 52px 30px; background:#fbfaf5; }
.status { flex:1; color:var(--coral); font-size:13px; margin:0; }
button { border:0; border-radius:10px; background:var(--teal); color:white; font:600 15px 'DM Sans',sans-serif; padding:14px 21px; cursor:pointer; box-shadow:0 5px 12px rgba(12,124,120,.2); }
button:hover { background:#096965; transform:translateY(-1px); }
button span { font-size:20px; vertical-align:-1px; margin-left:8px; }
.result { text-align:center; padding:27px 20px 30px; border-top:1px solid var(--line); }
.result-label { color:var(--muted); font-size:10px; letter-spacing:2px; font-weight:700; }
.score { color:var(--teal); font:700 46px 'Space Grotesk',sans-serif; line-height:1.15; margin:2px 0; }
.result p { color:var(--muted); font-size:13px; margin:0; }
footer { text-align:center; color:#9aa6a5; font-size:12px; padding-top:22px; } footer span { color:var(--coral); margin-left:5px; }
@media (max-width:650px) { .page-shell{padding-top:20px;width:calc(100% - 20px)} .quiz-header,.questions{padding-left:24px;padding-right:24px} .options{grid-template-columns:1fr;margin-left:30px} .action-row{padding-left:24px;padding-right:24px;align-items:flex-end;flex-direction:column-reverse;gap:10px} .status{width:100%;text-align:center} }

application.javascript:
document.addEventListener('DOMContentLoaded', function () {
  const form = document.getElementById('quiz-form');
  const scoreElement = document.querySelector('[data-testid="quiz-score"]');
  const status = document.getElementById('status');
  const resultCopy = document.getElementById('result-copy');
  const answers = ['Mars', 'Pacific Ocean', 'Carbon dioxide'];

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    const selected = answers.map(function (_, index) {
      const choice = form.querySelector('input[name="q' + (index + 1) + '"]:checked');
      return choice ? choice.value : null;
    });

    if (selected.some(function (value) { return value === null; })) {
      status.textContent = 'Please answer every question before submitting.';
      return;
    }

    const score = selected.reduce(function (total, value, index) {
      return total + (value === answers[index] ? 1 : 0);
    }, 0);
    scoreElement.textContent = score + ' / 3';
    scoreElement.setAttribute('data-score', String(score));
    status.textContent = '';
    resultCopy.textContent = score === 3 ? 'Perfect score — excellent work!' : score === 0 ? 'Keep exploring and try again.' : 'Nice work — keep building your knowledge.';
  });
});

