document.addEventListener('DOMContentLoaded', function () {
  const form = document.getElementById('quiz-form');
  const scoreElement = document.querySelector('[data-testid="quiz-score"]');
  const status = document.getElementById('status');
  const resultCopy = document.getElementById('result-copy');
  const answers = ['Mars', 'Pacific Ocean', 'Carbon dioxide'];

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    const selected = answers.map(function (_, index) {
      const choice = form.querySelector('input[name="q' + (index + 1) + '"]:checked');
      return choice ? choice.value : null;
    });

    if (selected.some(function (value) { return value === null; })) {
      status.textContent = 'Please answer every question before submitting.';
      return;
    }

    const score = selected.reduce(function (total, value, index) {
      return total + (value === answers[index] ? 1 : 0);
    }, 0);
    scoreElement.textContent = score + ' / 3';
    scoreElement.setAttribute('data-score', String(score));
    status.textContent = '';
    resultCopy.textContent = score === 3 ? 'Perfect score — excellent work!' : score === 0 ? 'Keep exploring and try again.' : 'Nice work — keep building your knowledge.';
  });
});

